import torch

def gen_inputs(ctx, device):
    shape = ctx['list__shape']
    dtype = getattr(torch, ctx['list__dtype'])
    n = shape[0]
    rest = shape[1:]
    if len(rest) == 0:
        rest = [1]
    span = max(1, rest[0] // 4)
    dim0s = torch.randint(-span, span + 1, (n,), device=device).tolist()
    tensors = []
    for j in range(n):
        s = tuple([max(1, rest[0] + dim0s[j])] + list(rest[1:]))
        tensors.append(torch.randn(s, dtype=dtype, device=device))
    return {'list': tensors}

def run(list):
    return torch.ops.aten._nested_tensor_from_tensor_list(list)

def validate(reference_outputs, candidate_outputs, candidate_args, ctx):
    ref = reference_outputs[0]
    cand = candidate_outputs[0]
    if not (isinstance(ref, torch.Tensor) and isinstance(cand, torch.Tensor)):
        return {"passed": False, "message": "outputs are not tensors"}
    if getattr(ref, 'is_nested', False) != getattr(cand, 'is_nested', False):
        return {"passed": False, "message": "nested flag differs"}
    if ref.dtype != cand.dtype:
        return {"passed": False, "message": "dtype differs"}
    if ref.layout != cand.layout:
        return {"passed": False, "message": "layout differs"}
    ref_vals = ref.values()
    cand_vals = cand.values()
    if ref_vals.shape != cand_vals.shape:
        return {"passed": False, "message": "values shape differs"}
    if torch.equal(ref_vals, cand_vals):
        return {"passed": True, "message": "", "metrics": {"matched_ratio": 1.0}}
    ok = bool(torch.allclose(ref_vals.float(), cand_vals.float(), rtol=1e-5, atol=1e-5))
    return {
        "passed": ok,
        "message": "" if ok else "nested tensor values differ",
        "metrics": {"matched_ratio": 1.0 if ok else 0.0},
    }
